def main():
    ap = argparse.ArgumentParser(description="Regenera el ZIP embebido.")
    ap.add_argument("-o", "--output", default=NOMBRE, help="ruta del zip de salida")
    ap.add_argument("--extract", metavar="DIR", help="extraer tambien el contenido en DIR")
    args = ap.parse_args()

    data = base64.b64decode("".join(_B64.split()))
    if len(data) != TAMANO or hashlib.sha256(data).hexdigest() != SHA256:
        sys.exit("ERROR: los datos embebidos estan corruptos (SHA-256 no coincide).")

    out = os.path.abspath(args.output)
    os.makedirs(os.path.dirname(out), exist_ok=True)
    with open(out, "wb") as f:
        f.write(data)
    print(f"Zip generado: {out} ({len(data):,} bytes, SHA-256 verificado)")

    if args.extract:
        with zipfile.ZipFile(out) as z:
            z.extractall(args.extract)
        print(f"Extraido en: {os.path.abspath(args.extract)}")


if __name__ == "__main__":
    main()
